#[inductive(reader_finish)]
fn reader_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Get the old and new local version values
    let old_local_version = pre.local_versions[node_id];
    let new_local_version = post.local_versions[node_id];

    // From the transition, we know that:
    // 1. The combiner state changed from Reading(Range{start, end, cur}) to Idle
    // 2. The local_versions[node_id] changed from some value to end
    // 3. The requirement was cur == end

    // From the reader state invariant, we know that if the pre-state had
    // CombinerState::Reading(ReaderState::Range{start, end, cur}), then:
    // - start == pre.local_versions[node_id]
    // - cur == end (from the requirement)
    // So new_local_version == end == cur == start == old_local_version

    // Actually looking at the transition more carefully:
    // - We remove combiner[node_id] => CombinerState::Reading(ReaderState::Range{start, end, cur}) 
    // - We add combiner[node_id] => CombinerState::Idle
    // - We remove local_versions[node_id] => _
    // - We add local_versions[node_id] => end
    // - We require cur == end
    //
    // From the invariant reader_state_valid, if we had a ReaderState::Range{start, end, cur}
    // then start == pre.local_versions[node_id] (which is old_local_version)
    // 
    // Therefore: new_local_version == end == cur, and from reader invariant start == old_local_version

    // Prove the upcoming_bits_are_not_alive invariant is preserved
    assert forall |i| post.tail <= i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat) + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {

        // The key observation is that only local_versions[node_id] changed.
        // Everything else (tail, alive_bits, buffer_size, num_replicas) stayed the same.

        // Case 1: If node_id was the node with minimum local version, then the minimum might have increased
        let old_min = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
        let new_min = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);

        if old_local_version == old_min {
            // The node that had the minimum local version has its value increased to new_local_version
            // The new minimum will be the minimum over all nodes, including the updated node_id

            // By definition of map_min_value, new_min >= old_min
            // More specifically, new_min >= min(old_min, new_local_version) = old_min (since new_local_version >= old_min)
            assert(new_min >= old_min);

            // Since the tail didn't change, and the range where bits should be not alive 
            // (from tail to min_local_version + buffer_size) possibly shrunk,
            // we need to show the invariant still holds

            // For the pre-state, we know:
            // forall |j| pre.tail <= j < old_min + pre.buffer_size ==> !log_entry_is_alive(pre.alive_bits, j, pre.buffer_size)

            // Since post.tail == pre.tail and post.buffer_size == pre.buffer_size and post.alive_bits == pre.alive_bits,
            // and new_min >= old_min, we have:
            // post.tail <= i < new_min + post.buffer_size and i in the range where we know the bits are not alive

            assert forall |j| pre.tail <= j < old_min + pre.buffer_size implies !log_entry_is_alive(pre.alive_bits, j, pre.buffer_size) by {
                // This follows from the pre-state invariant upcoming_bits_are_not_alive
                assert(true);
            };
        } else {
            // If node_id wasn't the minimum, then increasing local_versions[node_id] 
            // won't change the overall minimum (as we're taking the minimum over all nodes)
            assert(new_min == old_min);

            // Since nothing else changed, the property follows directly from the pre-state invariant
            assert forall |j| pre.tail <= j < old_min + pre.buffer_size implies !log_entry_is_alive(pre.alive_bits, j, pre.buffer_size) by {
                // This follows from the pre-state invariant upcoming_bits_are_not_alive
                assert(true);
            };
        }
