        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==>
        #[trigger] post.contents.contains_key(i)
    ) by {
        // Since tail, buffer_size, contents, and alive_bits didn't change,
        // and we're only updating a local version, we just need to check
        // how the condition (i < map_min_value(...)) might change

        // The contents map did not change
        assert(post.contents === pre.contents);
        assert(post.tail == pre.tail);
        assert(post.buffer_size == pre.buffer_size);
        assert(post.alive_bits === pre.alive_bits);

        // Case analysis based on whether i is less than the old or new minimum
        let old_min = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
        let new_min = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);

        // Apply the pre-state invariant
        assert forall |j: int| pre.tail - pre.buffer_size <= j < pre.tail ==> (
            (log_entry_is_alive(pre.alive_bits, j, pre.buffer_size) || j < old_min)
            <==> #[trigger] pre.contents.contains_key(j)
        ) by {
            // This is given by the invariant inv_buffer_contents on pre
