        // If it wasn't, then new_min == old_min
        // In either case, we need to show the equivalence holds for i in our range

        // Case: i < old_min
        if i < old_min {
            assert(i < new_min); // Because new_min >= old_min
            // Both sides of the equivalence are unchanged so it still holds
        } else {
