        // and the equivalence held in pre-state, it holds in post-state by preservation
        assert((log_entry_is_alive(post.alive_bits, i, post.buffer_size) || i < new_min)
             <==> post.contents.contains_key(i));
    }

    // Also prove the second part of inv_buffer_contents
    assert forall |i: int| post.tail <= i ==> ! #[trigger] post.contents.contains_key(i) by {
        // Contents didn't change and tail didn't change either
        assert(post.contents === pre.contents);
        assert(post.tail == pre.tail);
        // Directly follows from pre invariant
        assert(!pre.contents.contains_key(i));
    }
}

#[inductive(reader_finish)]
fn reader_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
    // In the reader_finish transition:
    // - combiner[node_id] changes from Reading(Range{start, end, cur}) to Idle
    // - local_versions[node_id] changes from old value to end
    // - Requirement: cur == end
    // 
    // From reader_state_valid invariant, if pre.combiner[node_id] == Reading(Range{start, end, cur}) then:
    // - start == pre.local_versions[node_id]
    // - cur == end (by requirement)
    // Therefore: post.local_versions[node_id] == end == cur == start == pre.local_versions[node_id]
    // This means the local_versions value doesn't actually change!

    assert(post.local_versions[node_id] == pre.local_versions[node_id]);
    assert(post.local_versions === pre.local_versions);

    // Since local_versions didn't change, and none of the other state fields changed:
    assert(post.tail == pre.tail);
    assert(post.buffer_size == pre.buffer_size);
    assert(post.alive_bits === pre.alive_bits);
    assert(post.contents === pre.contents);
    assert(post.num_replicas == pre.num_replicas);

    // All invariants are trivially preserved since the state is essentially unchanged

    // Specifically for upcoming_bits_are_not_alive:
    assert(map_min_value(post.local_versions, (post.num_replicas - 1) as nat) == 
           map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat));

    assert forall |i| post.tail <= i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat) + post.buffer_size
        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        // Follows directly from the pre-state invariant since all relevant values are unchanged
        assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
    };

    // For inv_buffer_contents:
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail ==> (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==>
        #[trigger] post.contents.contains_key(i)
    ) by {
        // Follows directly from the pre-state invariant
        assert((log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) ||
                i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat))
               <==> pre.contents.contains_key(i));
    };

    assert forall |i: int| post.tail <= i ==> ! #[trigger] post.contents.contains_key(i) by {
        // Follows directly from the pre-state invariant
        assert(!pre.contents.contains_key(i));
    };
}

