fn reader_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
    // In the reader_finish transition:
    // - combiner[node_id] changes from Reading(Range{start, end, cur}) to Idle
    // - local_versions[node_id] changes from old value to end
    // - Requirement: cur == end
    // 
    // From reader_state_valid invariant on pre-state, if pre.combiner[node_id] == Reading(Range{start, end, cur}) then:
    // - start == pre.local_versions[node_id]  (property of reader_state_valid)
    // - cur == end (required by transition)
    // Therefore: post.local_versions[node_id] == end == cur
    // And additionally: pre.local_versions[node_id] == start

