#[inductive(reader_finish)]
fn reader_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
    // From the transition, we know:
    // pre.combiner[node_id] == Reading(Range{start, end, cur})
    // post.combiner[node_id] == Idle
    // post.local_versions[node_id] == end
    // pre.local_versions[node_id] == start (from reader_state_valid invariant)
    // cur == end (requirement)

    // From reader_state_valid invariant on pre-state:
