        implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {

        // Key insight: we only changed one element in local_versions, so the map_min_value can only decrease or stay the same
        let pre_min = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
        let post_min = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);

        // post.local_versions only differs from pre.local_versions in position node_id
        // post.local_versions[node_id] == end and pre.local_versions[node_id] == start
