proof fn map_min_value_monotonic(m1: Map<NodeId, nat>, m2: Map<NodeId, nat>, idx: nat, changed_key: NodeId, new_val: nat)
    requires
        m1.dom() == m2.dom(),
        forall |k| #[trigger] m1.dom().contains(k) && k != changed_key ==> m1[k] == m2[k],
        m1.dom().contains(changed_key),
        m2[changed_key] == new_val,
        m1[changed_key] <= new_val,
        forall |k| #[trigger] m1.dom().contains(k) ==> m1.contains_key(k),
        forall |k| #[trigger] m2.dom().contains(k) ==> m2.contains_key(k),
    ensures
        map_min_value(m1, idx) <= map_min_value(m2, idx),
    decreases idx,
{
    if idx == 0 {
        // Base case
        assert(m1[0] <= m2[0]);
    } else {
        // Inductive case
        map_min_value_monotonic(m1, m2, (idx - 1) as nat, changed_key, new_val);
        // By inductive hypothesis and the fact that min(a,b) <= min(c,d) when a <= c and b <= d
    }
}

